basic.code:
-- All the columns of a small table
SELECT * FROM categories;

-- Only the columns you need, in the order you want
SELECT name, price, stock
FROM products
ORDER BY id;

-- One customer, by its key
SELECT * FROM customers WHERE id = 4;

-- Everything except one city
SELECT name, city FROM customers WHERE city <> 'Madrid' ORDER BY id;

-- Products that cost 3 euros or more
SELECT name, price
FROM products
WHERE price >= 3
ORDER BY price DESC;

-- Every city, once
SELECT DISTINCT city FROM customers ORDER BY city;

-- How many different products have ever been sold
SELECT count(*) AS lines, count(DISTINCT product_id) AS products
FROM order_items;

-- DISTINCT works on the whole row: each (city, year) pair once
SELECT DISTINCT city, substr(joined, 1, 4) AS year
FROM customers
ORDER BY city, year;

-- Change one row: always with a WHERE
UPDATE products SET stock = 50 WHERE name = 'Orange juice';

-- Several columns and an expression: 10% more on all Bakery items
UPDATE products
SET price = round(price * 1.10, 2), tags = '["bread", "promo"]'
WHERE category_id = 1;

-- Paid orders from before June are now shipped
UPDATE orders SET status = 'shipped'
WHERE status = 'paid' AND ordered < '2024-06-01';

SELECT id, name, price, stock, tags
FROM products
WHERE category_id = 1 OR id = 6
ORDER BY id;

-- How many reviews there are before deleting
SELECT count(*) AS reviews FROM reviews;

-- Delete the rows that match the WHERE
DELETE FROM reviews WHERE rating < 3;

-- A subquery picks what to delete: the reviews of Drinks products
DELETE FROM reviews
WHERE product_id IN (SELECT id FROM products WHERE category_id = 2);

SELECT id, product_id, rating, comment FROM reviews ORDER BY id;

-- A new table with its rules
CREATE TABLE suppliers (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL UNIQUE,
  country TEXT NOT NULL DEFAULT 'Spain',
  rating INTEGER CHECK (rating BETWEEN 1 AND 5),
  since TEXT
);

INSERT INTO suppliers (name, rating, since) VALUES
  ('Harinas del Sur', 5, '2022-02-01'),
  ('Lácteos Norte', 4, '2023-05-15');
INSERT INTO suppliers (name, country, rating) VALUES ('Fresh Fruit Ltd', 'UK', 3);

-- The table appears in the list on the left; PRAGMA describes it
SELECT name, type, "notnull", dflt_value, pk
FROM pragma_table_info('suppliers');

SELECT * FROM suppliers ORDER BY id;

advanced.code:
-- Move 5 croissants from the shop to an order, all or nothing
BEGIN;
UPDATE products SET stock = stock - 5 WHERE id = 2;
INSERT INTO order_items (order_id, product_id, qty, price)
VALUES (7, 2, 5, 1.50);
UPDATE orders SET total = total + 7.50 WHERE id = 7;
COMMIT;

-- Something goes wrong: undo everything since BEGIN
BEGIN;
DELETE FROM order_items;
SELECT count(*) AS lines_inside FROM order_items;
ROLLBACK;

-- A savepoint undoes only part of a transaction
BEGIN;
UPDATE products SET price = 0 WHERE id = 1;
SAVEPOINT before_milk;
UPDATE products SET price = 0 WHERE id = 7;
ROLLBACK TO before_milk;
UPDATE products SET price = 1.25 WHERE id = 1;
COMMIT;

SELECT p.id, p.name, p.price, p.stock,
       (SELECT count(*) FROM order_items) AS lines,
       (SELECT total FROM orders WHERE id = 7) AS order_7
FROM products AS p
WHERE p.id IN (1, 2, 7)
ORDER BY p.id;

-- A basket: one row per customer and product
CREATE TABLE baskets (
  customer_id INTEGER NOT NULL,
  product_id INTEGER NOT NULL,
  qty INTEGER NOT NULL,
  PRIMARY KEY (customer_id, product_id)
);

INSERT INTO baskets VALUES (1, 2, 2), (1, 7, 1), (3, 9, 1);

-- Add to the basket: insert, or add to the quantity if it exists
INSERT INTO baskets (customer_id, product_id, qty) VALUES (1, 2, 3)
ON CONFLICT (customer_id, product_id)
DO UPDATE SET qty = qty + excluded.qty;

INSERT INTO baskets (customer_id, product_id, qty) VALUES (3, 5, 2)
ON CONFLICT (customer_id, product_id)
DO UPDATE SET qty = qty + excluded.qty;

-- Ignore the duplicate instead of failing
INSERT INTO baskets VALUES (3, 9, 10) ON CONFLICT DO NOTHING;

SELECT b.customer_id AS cust, p.name, b.qty,
       round(b.qty * p.price, 2) AS amount
FROM baskets AS b
JOIN products AS p ON p.id = b.product_id
ORDER BY cust, p.name;

-- A log of price changes
CREATE TABLE price_log (
  product_id INTEGER,
  old_price REAL,
  new_price REAL
);

-- Runs by itself after every price change
CREATE TRIGGER log_price AFTER UPDATE OF price ON products
WHEN OLD.price <> NEW.price
BEGIN
  INSERT INTO price_log VALUES (OLD.id, OLD.price, NEW.price);
END;

-- Selling a line takes it out of stock and adds it to the order
CREATE TRIGGER sell AFTER INSERT ON order_items
BEGIN
  UPDATE products SET stock = stock - NEW.qty WHERE id = NEW.product_id;
  UPDATE orders SET total = round(total + NEW.qty * NEW.price, 2)
  WHERE id = NEW.order_id;
END;

UPDATE products SET price = round(price * 1.10, 2) WHERE category_id = 3;
INSERT INTO order_items (order_id, product_id, qty, price)
VALUES (9, 9, 1, 8.53);

SELECT p.name, l.old_price, l.new_price, p.stock,
       (SELECT total FROM orders WHERE id = 9) AS order_9
FROM price_log AS l
JOIN products AS p ON p.id = l.product_id
ORDER BY p.id;

-- Columns calculated from other columns of the same row
ALTER TABLE products
ADD COLUMN price_vat REAL AS (round(price * 1.21, 2));
ALTER TABLE products
ADD COLUMN first_tag TEXT AS (json_extract(tags, '$[0]'));

-- In a new table they can also be STORED on disk
CREATE TABLE invoice_lines (
  id INTEGER PRIMARY KEY,
  qty INTEGER NOT NULL,
  price REAL NOT NULL,
  net REAL AS (round(qty * price, 2)) STORED,
  vat REAL AS (round(net * 0.21, 2)) STORED
);
INSERT INTO invoice_lines (qty, price) VALUES (4, 2.40), (3, 1.20);

SELECT * FROM invoice_lines ORDER BY id;

-- They follow the data and can be indexed
UPDATE products SET price = 10.50 WHERE id = 4;
CREATE INDEX idx_products_first_tag ON products (first_tag);

SELECT name, price, price_vat, first_tag
FROM products
WHERE first_tag IN ('bread', 'coffee', 'fresh')
ORDER BY first_tag, name;

-- An ordinary table accepts any value in any column
CREATE TABLE loose (n INTEGER, price REAL);
INSERT INTO loose VALUES (1, 2.5), ('42', '3'), ('abc', 'cheap');
SELECT n, typeof(n) AS n_type, price, typeof(price) AS price_type
FROM loose
ORDER BY rowid;

-- A STRICT table checks the type of every value
CREATE TABLE strict_prices (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  price REAL NOT NULL CHECK (price > 0),
  extra ANY
) STRICT;

-- Values that convert without loss are accepted
INSERT INTO strict_prices (name, price, extra) VALUES
  ('Muffin', '1.80', 'abc'),
  ('Scone', 2, 42),
  ('Bagel', 1.35, NULL);

-- This one would fail: cannot store TEXT value in REAL column
-- INSERT INTO strict_prices (name, price) VALUES ('Tart', 'cheap');

SELECT name, price, typeof(price) AS price_type,
       extra, typeof(extra) AS extra_type
FROM strict_prices
ORDER BY id;

-- SQLite only checks foreign keys when you turn them on
PRAGMA foreign_keys;

CREATE TABLE wishlist (
  customer_id INTEGER NOT NULL
    REFERENCES customers (id) ON DELETE CASCADE,
  product_id INTEGER NOT NULL REFERENCES products (id),
  PRIMARY KEY (customer_id, product_id)
);

-- Still off: product 99 does not exist, but the row goes in
INSERT INTO wishlist VALUES (8, 4), (8, 9), (5, 12), (5, 2), (5, 99);

-- foreign_key_check lists the rows that break a foreign key
PRAGMA foreign_key_check;

-- Clean up, then turn the checks on for this connection
DELETE FROM wishlist WHERE product_id NOT IN (SELECT id FROM products);
PRAGMA foreign_keys = ON;

-- Deleting a customer also deletes their wishlist (CASCADE)
DELETE FROM customers WHERE id = 8;

SELECT w.customer_id, c.name AS customer, p.name AS product
FROM wishlist AS w
JOIN customers AS c ON c.id = w.customer_id
JOIN products AS p ON p.id = w.product_id
ORDER BY p.name;
